    options.recordSuccess(kind);
    return result;
  } catch (error) {
    options.recordFailure();
    throw error;
  }
}

export function normalizeAndValidatePath(input: string): string {
  const path = input.trim().replace(/^\.\//, "");
  if (
    path.startsWith("/") ||
